import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis, BarChart, Bar } from 'recharts';
import { LifeBuoy, ArrowDownRight, ArrowRight, ArrowUpRight, BadgeCheck, Bell, BookOpen, ChartNoAxesCombined, ChevronDown, CircleDollarSign, ClipboardList, Download, Droplets, Heart, HeartHandshake, LayoutDashboard, LogOut, Menu, MoreHorizontal, Plus, Search, Settings, ShieldCheck, Sprout, Users, Wallet, X } from 'lucide-react';
import './styles.css';
