const api=axios.create({baseURL:'/api'});
api.interceptors.request.use(config=>{const t=localStorage.getItem('token');if(t)config.headers.Authorization=`Bearer ${t}`;return config;});
api.interceptors.response.use(response=>response,async error=>{const original=error.config;if(error.response?.status===401&&original&&!original._retried&&localStorage.getItem('refreshToken')){original._retried=true;try{const r=await axios.post('/api/auth/refresh',{refreshToken:localStorage.getItem('refreshToken')});localStorage.setItem('token',r.data.token);localStorage.setItem('refreshToken',r.data.refreshToken);original.headers.Authorization=`Bearer ${r.data.token}`;return api(original)}catch{localStorage.removeItem('token');localStorage.removeItem('refreshToken');localStorage.removeItem('user')}}return Promise.reject(error)});
const Auth=createContext(null); const useAuth=()=>useContext(Auth);
const listData=d=>Array.isArray(d)?d:(d?.items||[]);
const campaignVisual=c=>c?.imageUrl?{backgroundImage:`linear-gradient(0deg,#102a4355,transparent),url("${c.imageUrl}")`,backgroundSize:'cover',backgroundPosition:'center'}:undefined;
const shortDate=d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
function App(){const [user,setUser]=useState(()=>{try{return JSON.parse(localStorage.getItem('user'))}catch{return null}});const value=useMemo(()=>({user,setUser,login(data){localStorage.setItem('token',data.token);if(data.refreshToken)localStorage.setItem('refreshToken',data.refreshToken);localStorage.setItem('user',JSON.stringify(data.user));setUser(data.user)},logout(){const current=localStorage.getItem('token');if(current)api.post('/auth/logout',{}, {headers:{Authorization:`Bearer ${current}`}}).catch(()=>{});localStorage.removeItem('token');localStorage.removeItem('refreshToken');localStorage.removeItem('user');setUser(null)}}),[user]);return <Auth.Provider value={value}><BrowserRouter><Routes><Route path="/" element={<Home/>}/><Route path="/campaigns" element={<Campaigns/>}/><Route path="/campaigns/:id" element={<CampaignDetail/>}/><Route path="/donate/:campaignId" element={<Donate/>}/><Route path="/donation/success/:id" element={<Success/>}/><Route path="/login" element={<Login/>}/><Route path="/register" element={<Register/>}/><Route path="/forgot-password" element={<RecoveryPage api={api}/>}/><Route path="/reset-password" element={<RecoveryPage api={api} reset/>}/><Route path="/admin/*" element={<Protected admin><AdminShell/></Protected>}/><Route path="/donor/*" element={<Protected donor><DonorShell/></Protected>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></BrowserRouter></Auth.Provider>}
function Protected({children,admin=false,donor=false}){const{user}=useAuth();return !user?<Navigate to="/login" replace/>:(admin&&user.role!=='ADMIN'?<Navigate to="/donor/dashboard" replace/>:donor&&user.role!=='DONOR'?<Navigate to="/admin/dashboard" replace/>:children)}
function Header(){const{user,logout}=useAuth();return <header className="topbar public-nav"><Link className="brand" to="/"><span className="brandmark"><HeartHandshake size={20}/></span> goodwill<span className="brand-dot">.</span></Link><nav><Link to="/campaigns">Our causes</Link><a href="/#impact">Our impact</a><a href="/#about">About us</a></nav><div className="nav-actions">{user?<Link className="btn btn-light" to={user.role==='ADMIN'?'/admin/dashboard':'/donor/dashboard'}>My account <ArrowRight size={16}/></Link>:<><Link className="nav-login" to="/login">Log in</Link><Link className="btn btn-dark" to="/campaigns">Give today <ArrowRight size={16}/></Link></>}</div></header>}
const fallback=[{id:'c1',slug:'clean-water-for-all',title:'Clean Water for All',category:'Water',description:'Bring safe, reliable drinking water to rural communities through wells, filtration and local stewardship.',target:50000,raised:34750,icon:'💧',status:'ACTIVE'},{id:'c2',slug:'learning-without-limits',title:'Learning Without Limits',category:'Education',description:'Equip children with books, classroom materials and the support to stay curious.',target:35000,raised:22900,icon:'📚',status:'ACTIVE'},{id:'c3',slug:'community-health-access',title:'Community Health Access',category:'Health',description:'Make essential health screenings and care accessible to families who need them most.',target:40000,raised:18400,icon:'🩺',status:'ACTIVE'},{id:'c4',slug:'a-greener-tomorrow',title:'A Greener Tomorrow',category:'Environment',description:'Restore native habitats and grow resilient, greener neighborhoods together.',target:28000,raised:14600,icon:'🌱',status:'ACTIVE'},{id:'c5',slug:'meals-that-matter',title:'Meals That Matter',category:'Food security',description:'Connect local kitchens and volunteers to families facing food insecurity.',target:22000,raised:9400,icon:'🥗',status:'ACTIVE'}];
function Home(){const[campaigns,setCampaigns]=useState(fallback);useEffect(()=>{api.get('/campaigns').then(r=>setCampaigns(listData(r.data).filter(c=>c.status==='ACTIVE'))).catch(()=>{})},[]);return <><Header/><main><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-line"/>A little good goes a long way</div><h1>Make kindness<br/>go <em>further.</em></h1><p>Every act of generosity can change someone's story. Find a cause close to your heart and be part of what's possible.</p><div className="hero-buttons"><Link className="btn btn-teal" to="/campaigns">Explore our causes <ArrowRight size={17}/></Link><a className="text-link" href="#about">How we make a difference <ArrowDownRight size={17}/></a></div><div className="proof"><div className="avatars"><b>AJ</b><b>EC</b><b>SP</b><b>+2k</b></div><div><strong>2,400+ kind people</strong><span>have already made a difference</span></div></div></div><div className="hero-visual"><div className="hero-image"><div className="image-wash"/><div className="floating-note"><span className="note-icon"><Droplets size={18}/></span><div><strong>Clean water, closer.</strong><small>Community progress</small></div><span className="note-up">+24%</span></div><div className="image-caption"><span>01 / 05</span><i/> Together, we make it possible.</div></div><div className="side-label">PEOPLE FIRST · ALWAYS</div></div><div className="hero-orbit"/></section><section className="trust-row"><div><ShieldCheck size={20}/><span>Every donation is handled with care</span></div><div><BadgeCheck size={20}/><span>Transparent impact, always</span></div><div><Heart size={20}/><span>100% heart, zero pressure</span></div></section><section className="section causes-section" id="impact"><div className="section-heading"><div><div className="eyebrow">GOOD THINGS ARE HAPPENING</div><h2>Causes worth<br/>showing up for.</h2></div><Link className="text-link" to="/campaigns">See all causes <ArrowRight size={17}/></Link></div><div className="cause-grid">{campaigns.slice(0,3).map((c,i)=><CampaignCard key={c.id} campaign={c} index={i}/>)}</div></section><section className="impact-band" id="about"><div className="impact-art"><div className="impact-circle">kindness<br/><strong>adds up.</strong></div><span>SMALL ACTS, LASTING CHANGE</span></div><div className="impact-copy"><div className="eyebrow">A DIFFERENT KIND OF GIVING</div><h2>Good giving<br/>feels <em>good.</em></h2><p>We believe helping should be simple, honest, and human. See where your generosity goes, and the people whose lives it touches.</p><Link className="btn btn-dark" to="/campaigns">Find your cause <ArrowRight size={16}/></Link><div className="impact-stat"><strong>$1.2m</strong><span>directed to communities<br/>with care and transparency</span></div></div></section><section className="quote-section"><span>“</span><blockquote>When people come together, small things become a big reason to hope.</blockquote><p>THE GOODWILL COMMUNITY</p></section></main><Footer/></>}
function Footer(){return <footer><Link className="brand" to="/"><span className="brandmark"><HeartHandshake size={18}/></span> goodwill<span className="brand-dot">.</span></Link><span>Giving that feels good. © 2026 Goodwill Foundation</span><div><Link to="/campaigns">Our causes</Link><Link to="/login">My account</Link></div></footer>}
function CampaignCard({campaign:c,index=0}){const pct=Math.min(100,Math.round(c.raised/c.target*100));return <article className={`cause-card card-tone-${index%3}`}><Link className="cause-art" style={campaignVisual(c)} to={`/campaigns/${c.id}`}><span className="cause-category">{c.category}</span><span className="cause-emoji">{c.icon||['💧','📚','🌿'][index%3]}</span><span className="cause-art-caption">GOOD THINGS GROW HERE</span></Link><div className="cause-body"><Link to={`/campaigns/${c.id}`}><h3>{c.title}</h3></Link><p>{c.description}</p><div className="progress-head"><strong>{money(c.raised)} <small>raised</small></strong><span>{pct}%</span></div><div className="progress-track"><i style={{width:`${pct}%`}}/></div><div className="cause-foot"><span>of {money(c.target)} goal</span><Link to={`/donate/${c.id}`} aria-label={`Donate to ${c.title}`}><ArrowRight size={18}/></Link></div></div></article>}
function Campaigns(){const[items,setItems]=useState(fallback),[query,setQuery]=useState(''),[category,setCategory]=useState('ALL'),[page,setPage]=useState(1),[paging,setPaging]=useState({pages:1,total:fallback.length}),[loading,setLoading]=useState(true);useEffect(()=>{setLoading(true);api.get('/campaigns',{params:{q:query||undefined,category:category==='ALL'?undefined:category,page,limit:12}}).then(r=>{setItems(listData(r.data).filter(c=>c.status==='ACTIVE'));setPaging(r.data.pagination||{page:1,pages:1,total:listData(r.data).length})}).catch(()=>{}).finally(()=>setLoading(false))},[query,category,page]);const filtered=items.filter(c=>`${c.title} ${c.category}`.toLowerCase().includes(query.toLowerCase())&&(category==='ALL'||c.category===category));return <><Header/><div className="listing-hero"><div className="eyebrow">FIND YOUR SOMETHING</div><h1>Good causes.<br/><em>Real change.</em></h1><p>Big change starts with people who care. Find the cause that speaks to you.</p><div className="listing-filters"><div className="listing-search"><Search size={18}/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search by cause or category"/></div><select value={category} onChange={e=>{setCategory(e.target.value);setPage(1)}}><option value="ALL">All categories</option>{[...new Set(items.map(c=>c.category))].map(c=><option key={c} value={c}>{c}</option>)}</select></div><span className="result-count">{paging.total} active causes</span></div><section className="section listing-grid">{loading?<div className="empty-state">Finding good things…</div>:filtered.length?filtered.map((c,i)=><CampaignCard key={c.id} campaign={c} index={i}/>):<div className="empty-state">No causes match that search yet. Try another word.</div>}<PageControls page={page} pages={paging.pages||1} onChange={setPage}/></section><Footer/></>}
function CampaignDetail(){const{id}=useParams();const[c,setC]=useState(fallback.find(x=>x.id===id||x.slug===id));const{user}=useAuth();const[saved,setSaved]=useState(false),[following,setFollowing]=useState(false);const[message,setMessage]=useState('');useEffect(()=>{api.get(`/campaigns/${id}`).then(r=>setC(r.data)).catch(()=>{});if(user?.role==='DONOR')Promise.all([api.get('/donor/saved-campaigns'),api.get('/donor/followed-campaigns')]).then(([a,b])=>{setSaved(listData(a.data).some(x=>x.id===id));setFollowing(listData(b.data).some(x=>x.id===id))}).catch(()=>{})},[id,user?.role]);async function toggle(kind){if(!user){window.location.href='/login';return}const path=`/donor/${kind}-campaigns/${c.id}`;try{const isOn=kind==='saved'?saved:following;await api[isOn?'delete':'post'](path);kind==='saved'?setSaved(!isOn):setFollowing(!isOn);setMessage(isOn?'Campaign removed from your list.':'Campaign added to your list.')}catch(e){setMessage(e.response?.data?.error||'Could not update campaign preference.')}}if(!c)return <><Header/><div className="empty-state">This campaign could not be found.</div></>;return <><Header/><section className="detail-wrap"><Link className="back-link" to="/campaigns">← All causes</Link><div className="detail-card"><div className="detail-art" style={campaignVisual(c)}><span>{c.category}</span><b>{c.icon||'💙'}</b><small>GOOD THINGS GROW HERE</small></div><div className="detail-info"><div className="eyebrow">YOUR GENEROSITY IN ACTION</div><h1>{c.title}</h1><p>{c.description}</p><div className="detail-raised"><b>{money(c.raised)}</b> raised of {money(c.target)} goal</div><div className="progress-track"><i style={{width:`${Math.min(100,c.raised/c.target*100)}%`}}/></div><p className="detail-note">Together, every gift helps build something lasting.</p><Link className="btn btn-teal" to={`/donate/${c.id}`}>Support this cause <ArrowRight size={16}/></Link>{user?.role==='DONOR'&&<div className="campaign-save-actions"><button className={saved?'saved':''} onClick={()=>toggle('saved')}><Heart size={15}/>{saved?'Saved':'Save campaign'}</button><button className={following?'saved':''} onClick={()=>toggle('followed')}><Bell size={15}/>{following?'Following':'Follow updates'}</button></div>}{message&&<small className="campaign-save-message">{message}</small>}</div></div></section><Footer/></>}
function Donate(){const{campaignId}=useParams();const c=fallback.find(x=>x.id===campaignId||x.slug===campaignId);const[info,setInfo]=useState(c);const[amount,setAmount]=useState('100');const[fields,setFields]=useState({name:'',email:'',anonymous:false,simulate:'success',method:'DEMO_CARD',message:''});const[busy,setBusy]=useState(false);const[error,setError]=useState('');const nav=useNavigate();const{user}=useAuth();const idempotencyKey=useRef(crypto.randomUUID());useEffect(()=>{api.get(`/campaigns/${campaignId}`).then(r=>setInfo(r.data)).catch(()=>{});if(user?.role==='DONOR'){Promise.all([api.get('/donor/profile'),api.get('/donor/preferences')]).then(([p,d])=>{setFields(v=>({...v,name:p.data.name,email:p.data.email,anonymous:d.data.anonymousDefault,method:d.data.paymentMethod||'DEMO_CARD',message:d.data.donationMessage||''}));if(d.data.preferredAmount)setAmount(String(d.data.preferredAmount))}).catch(()=>{})}},[campaignId,user?.role]);function change(e){idempotencyKey.current=crypto.randomUUID();setFields({...fields,[e.target.name]:e.target.type==='checkbox'?e.target.checked:e.target.value})}async function submit(e){e.preventDefault();setBusy(true);setError('');try{const r=await api.post('/donations',{campaignId:info.id,amount:Number(amount),name:fields.name,email:fields.email,anonymous:fields.anonymous,simulate:fields.simulate,method:fields.method,message:fields.message||undefined},{headers:{'Idempotency-Key':idempotencyKey.current}});nav(`/donation/success/${r.data.donation.id}`,{state:r.data});}catch(e){setError(e.response?.data?.error||'We could not process this gift. Please try again.')}finally{setBusy(false)}}if(!info)return <><Header/><div className="empty-state">Loading campaign…</div></>;return <><Header/><div className="donate-layout"><div className="donate-main"><Link className="back-link" to={`/campaigns/${info.id}`}>← Back to campaign</Link><div className="eyebrow">A MOMENT OF GENEROSITY</div><h1>Your gift can<br/>make a <em>difference.</em></h1><p className="muted">You're supporting <strong>{info.title}</strong></p><form onSubmit={submit} className="donate-form"><label className="field-label">Choose an amount</label><div className="amount-picks">{['25','50','100','250'].map(n=><button type="button" className={amount===n?'selected':''} onClick={()=>{idempotencyKey.current=crypto.randomUUID();setAmount(n)}} key={n}>${n}</button>)}</div><label className="field-label" htmlFor="amount">Or enter your amount</label><div className="amount-input"><span>$</span><input id="amount" type="number" min="1" step="0.01" value={amount} onChange={e=>{idempotencyKey.current=crypto.randomUUID();setAmount(e.target.value)}} required/></div><div className="form-two"><label><span className="field-label">Your name</span><input name="name" value={fields.name} onChange={change} placeholder="Jordan Smith" required minLength="2"/></label><label><span className="field-label">Email address</span><input type="email" name="email" value={fields.email} onChange={change} placeholder="you@example.com" required/></label></div><label className="field-label" htmlFor="demo-method">Demo payment method</label><select id="demo-method" name="method" value={fields.method} onChange={change}><option value="DEMO_CARD">Demo card</option><option value="DEMO_BANK">Demo bank transfer</option></select><label className="field-label">Optional message</label><textarea name="message" maxLength="500" value={fields.message} onChange={change} placeholder="A note to include with your gift"/><label className="checkline"><input type="checkbox" name="anonymous" checked={fields.anonymous} onChange={change}/> Keep my gift anonymous</label><label className="checkline demo-select"><input type="checkbox" checked={fields.simulate==='failure'} onChange={e=>{idempotencyKey.current=crypto.randomUUID();setFields({...fields,simulate:e.target.checked?'failure':'success'})}}/> Simulate a failed demo payment (no real payment is taken)</label>{error&&<div className="form-error">{error}</div>}<button className="btn btn-teal donate-submit" disabled={busy}>{busy?'Recording your gift…':<>Give {money(Number(amount))} <ArrowRight size={17}/></>}</button><p className="secure-note"><ShieldCheck size={15}/> Safe demo checkout · No card details collected</p></form></div><aside className="donate-aside"><div className="aside-art"><span>{info.category}</span><b>{info.icon||'💙'}</b></div><div className="aside-copy"><div className="eyebrow">YOUR GIFT SUPPORTS</div><h3>{info.title}</h3><p>{info.description}</p><div className="aside-row"><span>Campaign goal</span><b>{money(info.target)}</b></div><div className="aside-row"><span>Already raised</span><b>{money(info.raised)}</b></div><p className="donation-disclaimer">This is a demonstration donation. No actual money is collected.</p></div></aside></div><Footer/></>}
function Success(){const{id}=useParams();const{state}=useLocationShim();const{user}=useAuth();const[donation,setDonation]=useState(state?.donation),[error,setError]=useState('');useEffect(()=>{if(!donation)api.get('/donations').then(r=>setDonation(listData(r.data).find(d=>d.id===id))).catch(()=>{})},[id]);const c=donation&&fallback.find(x=>x.id===donation.campaignId);async function retry(){try{const r=await api.post(`/donations/${id}/retry`);setDonation(r.data.donation);setError('')}catch(e){setError(e.response?.data?.error||'Could not retry this gift.')}}return <><Header/><div className="success-wrap"><div className={`success-icon ${donation?.status==='FAILED'?'failed':''}`}>{donation?.status==='FAILED'?<X/>:<BadgeCheck/>}</div><div className="eyebrow">{donation?.status==='FAILED'?'DEMO PAYMENT FAILED':'A LITTLE GOOD, DONE'}</div><h1>{donation?.status==='FAILED'?'Your gift wasn’t completed.':'Thank you for showing up.'}</h1><p>{donation?.status==='FAILED'?'This simulated payment failed. You can retry it from your donor account.':'Your generosity is part of something bigger. We’re glad you’re here.'}</p>{donation&&<div className="receipt-mini"><span>Gift amount</span><strong>{money(donation.amount)}</strong><span>Campaign</span><strong>{donation.campaignTitle||c?.title||'Goodwill cause'}</strong>{donation.receiptNumber&&<><span>Receipt</span><strong>{donation.receiptNumber}</strong></>}</div>}{error&&<div className="form-error">{error}</div>}{donation?.status==='FAILED'&&(user?<button className="btn btn-teal" onClick={retry}>Retry demo payment <ArrowRight size={16}/></button>:<Link className="btn btn-teal" to="/login">Sign in to retry <ArrowRight size={16}/></Link>)}{donation?.status!=='FAILED'&&<Link className="btn btn-teal" to="/campaigns">Explore more causes <ArrowRight size={16}/></Link>}</div><Footer/></>}
function useLocationShim(){return useLocation();}
function Login(){const{login}=useAuth();const nav=useNavigate();const[email,setEmail]=useState('admin@goodwill.demo'),[password,setPassword]=useState('DemoAdmin!23'),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);setError('');try{const r=await api.post('/auth/login',{email,password});login(r.data);nav(r.data.user.role==='ADMIN'?'/admin/dashboard':'/donor/dashboard')}catch(e){setError(e.response?.data?.error||'Could not sign in.')}finally{setBusy(false)}}return <><Header/><div className="auth-page"><div className="auth-card"><div className="brandmark"><HeartHandshake size={22}/></div><div className="eyebrow">WELCOME BACK</div><h1>Good to see you.</h1><p>Sign in to pick up where your kindness left off.</p><form onSubmit={submit}><label className="field-label">Email address</label><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/><label className="field-label">Password</label><input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/>{error&&<div className="form-error">{error}</div>}<button className="btn btn-teal" disabled={busy}>{busy?'Signing in…':'Sign in'} <ArrowRight size={16}/></button></form><p className="auth-switch"><Link to="/forgot-password">Forgot your password?</Link></p><div className="demo-credentials"><strong>Demo access</strong><span>Admin: admin@goodwill.demo</span><span>Password: DemoAdmin!23</span></div><p className="auth-switch">New to Goodwill? <Link to="/register">Create an account</Link></p></div></div><Footer/></>}
function Register(){const{login}=useAuth();const nav=useNavigate();const[fields,setFields]=useState({name:'',email:'',password:''}),[error,setError]=useState('');async function submit(e){e.preventDefault();try{const r=await api.post('/auth/register',fields);login(r.data);nav('/donor/dashboard')}catch(e){setError(e.response?.data?.error||'Could not create your account.')}}return <><Header/><div className="auth-page"><div className="auth-card"><div className="brandmark"><HeartHandshake size={22}/></div><div className="eyebrow">JOIN A COMMUNITY OF GOOD</div><h1>Let's do good.</h1><p>Create your account to keep track of your giving and receipts.</p><form onSubmit={submit}><label className="field-label">Your name</label><input value={fields.name} onChange={e=>setFields({...fields,name:e.target.value})} required/><label className="field-label">Email address</label><input type="email" value={fields.email} onChange={e=>setFields({...fields,email:e.target.value})} required/><label className="field-label">Password (8+ characters)</label><input type="password" minLength="8" value={fields.password} onChange={e=>setFields({...fields,password:e.target.value})} required/>{error&&<div className="form-error">{error}</div>}<button className="btn btn-teal">Create account <ArrowRight size={16}/></button></form><p className="auth-switch">Already have an account? <Link to="/login">Sign in</Link></p></div></div><Footer/></>}

const adminNav=[['Overview','/admin/dashboard',LayoutDashboard],['Donors','/admin/donors',Users],['Campaigns','/admin/campaigns',Heart],['Donations','/admin/donations',Wallet],['Receipts','/admin/receipts',ClipboardList],['Reports','/admin/reports',ChartNoAxesCombined],['Activity','/admin/activity',ShieldCheck],['Support','/admin/support',LifeBuoy],['Settings','/admin/settings',Settings]];
function AdminShell(){const{user,logout}=useAuth();const[open,setOpen]=useState(false);return <div className="app-shell"><aside className={`sidebar ${open?'sidebar-open':''}`}><Link className="brand side-brand" to="/"><span className="brandmark"><HeartHandshake size={19}/></span> goodwill<span className="brand-dot">.</span></Link><div className="workspace-label">WORKSPACE</div><div className="nav-list">{adminNav.map(([label,path,Icon])=><NavLink key={path} to={path} onClick={()=>setOpen(false)} className={({isActive})=>`side-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span>{label==='Activity'&&<i className="nav-dot"/>}</NavLink>)}</div><div className="sidebar-bottom"><div className="side-help"><span className="help-icon"><Heart size={15}/></span><strong>Doing good,<br/>together.</strong><small>Every gift tells a story.</small></div><button className="side-profile" onClick={logout}><span className="avatar">{user?.name?.split(' ').map(x=>x[0]).join('')}</span><span><strong>{user?.name||'Admin'}</strong><small>Administrator</small></span><LogOut size={16}/></button><Link className="back-public" to="/">← View public site</Link></div></aside><main className="workspace"><div className="mobile-top"><button onClick={()=>setOpen(!open)}><Menu/></button><span>Goodwill</span><Bell size={18}/></div><div className="workspace-top"><div><div className="crumb">Goodwill <span>/</span> <strong>Workspace</strong></div><span className="top-welcome">Making good things happen <span>✦</span></span></div><div className="top-user"><NotificationMenu/><span className="avatar">{user?.name?.split(' ').map(x=>x[0]).join('')}</span><div><strong>{user?.name}</strong><small>Goodwill Foundation</small></div><ChevronDown size={15}/></div></div><Routes><Route path="dashboard" element={<Dashboard/>}/><Route path="donors" element={<DonorAdmin/>}/><Route path="campaigns" element={<CampaignAdmin/>}/><Route path="donations" element={<DataPage type="donations"/>}/><Route path="receipts" element={<DataPage type="receipts"/>}/><Route path="reports" element={<Reports/>}/><Route path="activity" element={<Activity/>}/><Route path="support" element={<SupportAdmin api={api}/>}/><Route path="settings" element={<SettingsPage/>}/><Route path="*" element={<Dashboard/>}/></Routes></main></div>}
function PageTitle({eyebrow,title,subtitle,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function PageControls({page,pages,onChange}){return pages>1?<div className="page-controls"><button disabled={page<=1} onClick={()=>onChange(page-1)}>← Previous</button><span>Page {page} of {pages}</span><button disabled={page>=pages} onClick={()=>onChange(page+1)}>Next →</button></div>:null}
function NotificationMenu(){const[open,setOpen]=useState(false),[items,setItems]=useState([]);async function toggle(){if(!open){try{const r=await api.get('/notifications');setItems(r.data)}catch{}}setOpen(!open)}async function mark(item){await api.patch(`/notifications/${item.id}/read`);setItems(items.map(x=>x.id===item.id?{...x,readAt:new Date().toISOString()}:x))}const unread=items.filter(x=>!x.readAt).length;return <div className="notification-menu"><button className="icon-button" onClick={toggle} aria-label="Notifications"><Bell size={19}/>{unread>0&&<i/>}</button>{open&&<div className="notification-popover"><div className="notification-head"><strong>Notifications</strong><span>{unread} new</span></div>{items.length?items.map(item=><button key={item.id} className={`notification-item ${item.readAt?'read':''}`} onClick={()=>mark(item)}><b>{item.title}</b><span>{item.message}</span><small>{shortDate(item.createdAt)}</small></button>):<div className="notification-empty">You're all caught up.</div>}</div>}</div>}
function Dashboard(){const[data,setData]=useState(null);useEffect(()=>{api.get('/dashboard').then(r=>setData(r.data)).catch(()=>{})},[]);const d=data||{total:125050,donors:1248,activeCampaigns:5,transactions:397,monthly:[{month:'Jun',amount:14000},{month:'Jul',amount:18000},{month:'Aug',amount:21000},{month:'Sep',amount:17000},{month:'Oct',amount:26000},{month:'Nov',amount:29000}],campaigns:fallback,recent:[]};return <div className="page-content"><PageTitle eyebrow="THURSDAY, NOVEMBER 12, 2026" title="Good morning, Alex ✨" subtitle="Here's what's happening with your community today." action={<button className="btn btn-light" onClick={()=>api.get('/reports/export.csv').then(r=>download(r.data,'donation-report.csv'))}><Download size={16}/> Export overview</button>}/><div className="metric-grid">{[[CircleDollarSign,'Total donations',money(d.total),'Successful gifts only','teal'],[Users,'Registered donors',d.donors.toLocaleString(),'Donor records','blue'],[Heart,'Active campaigns',d.activeCampaigns,'Accepting donations','peach'],[BadgeCheck,'Successful gifts',d.transactions,'Successful payments','purple'],[ChartNoAxesCombined,'All campaigns',d.totalCampaigns??d.campaigns.length,'Across every status','blue'],[ClipboardList,'Completed campaigns',d.completedCampaigns??0,'Campaigns marked complete','teal'],[X,'Failed attempts',d.failedTransactions??0,'No receipt issued','peach']].map(([Icon,label,value,trend,color])=><article className="metric-card" key={label}><div className={`metric-icon ${color}`}><Icon size={19}/></div><span>{label}</span><strong>{value}</strong><small>{trend}</small></article>)}</div><div className="analytics-grid"><section className="panel chart-panel"><div className="panel-head"><div><h2>Giving over time</h2><p>Successful donations by month</p></div><span className="period-select">Last 6 months <ChevronDown size={14}/></span></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={d.monthly} margin={{top:10,right:8,left:-22,bottom:0}}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#64c9bc" stopOpacity={.27}/><stop offset="100%" stopColor="#64c9bc" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf1f3"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#8a99a3',fontSize:12}} dy={10}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#8a99a3',fontSize:11}} tickFormatter={x=>`$${x/1000}k`}/><Tooltip formatter={v=>money(v)}/><Area type="monotone" dataKey="amount" stroke="#168c8a" strokeWidth={2.5} fill="url(#chartFill)"/></AreaChart></ResponsiveContainer></div><div className="chart-legend"><i/> Donations <span>·</span> USD</div></section><section className="panel campaign-panel"><div className="panel-head"><div><h2>Campaign pulse</h2><p>Progress toward each goal</p></div><Link to="/admin/campaigns" className="icon-link"><MoreHorizontal/></Link></div><div className="campaign-pulse">{d.campaigns.slice(0,5).map((c,i)=><div className="pulse-row" key={c.id}><span className={`pulse-emoji pulse-${i}`}>{c.icon||'💙'}</span><div className="pulse-info"><div><strong>{c.title}</strong><span>{Math.min(100,Math.round(c.raised/c.target*100))}%</span></div><div className="progress-track"><i style={{width:`${Math.min(100,c.raised/c.target*100)}%`}}/></div><small>{money(c.raised)} <em>of</em> {money(c.target)}</small></div></div>)}</div><Link className="panel-footer-link" to="/admin/campaigns">View all campaigns <ArrowRight size={15}/></Link></section></div><section className="panel recent-panel"><div className="panel-head"><div><h2>Recent giving</h2><p>The latest acts of generosity</p></div><Link to="/admin/donations" className="text-link">View all <ArrowRight size={15}/></Link></div><DonationTable rows={d.recent.slice(0,5)}/></section></div>}
function DonationTable({rows}){return <div className="table-wrap"><table><thead><tr><th>DONOR</th><th>CAMPAIGN</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th>REFERENCE</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.id}><td><div className="person-cell"><span className={`avatar avatar-${i%5}`}>{r.anonymous?'✦':r.donorName?.split(' ').map(x=>x[0]).join('')}</span><strong>{r.anonymous?'Anonymous supporter':r.donorName}</strong></div></td><td>{r.campaign}</td><td>{shortDate(r.createdAt)}</td><td className="amount-cell">{money(r.amount)}</td><td><span className={`status ${r.status==='SUCCEEDED'?'status-success':'status-failed'}`}><i/>{r.status==='SUCCEEDED'?'Successful':'Failed'}</span></td><td className="ref-cell">{r.transactionRef}</td></tr>)}</tbody></table>{!rows.length&&<div className="empty-small">No recent donations yet.</div>}</div>}
function DonorAdmin(){const[rows,setRows]=useState([]),[query,setQuery]=useState(''),[page,setPage]=useState(1),[paging,setPaging]=useState({pages:1,total:0}),[profile,setProfile]=useState(null),[show,setShow]=useState(false),[form,setForm]=useState({name:'',email:'',phone:''}),[error,setError]=useState('');const load=()=>api.get('/donors',{params:{q:query||undefined,page,limit:20}}).then(r=>{setRows(listData(r.data));setPaging(r.data.pagination||{page:1,pages:1,total:listData(r.data).length})}).catch(()=>{});useEffect(()=>{load()},[page,query]);const filtered=rows.filter(x=>`${x.name} ${x.email}`.toLowerCase().includes(query.toLowerCase()));async function create(e){e.preventDefault();try{await api.post('/donors',form);setShow(false);setForm({name:'',email:'',phone:''});setError('');load()}catch(e){setError(e.response?.data?.error||'Could not add donor.')}}async function edit(d){const name=window.prompt('Update donor name',d.name);if(name&&name.trim()){try{await api.patch(`/donors/${d.id}`,{name:name.trim()});load()}catch{window.alert('Could not update donor.')}}}async function toggle(d){try{await api.patch(`/donors/${d.id}`,{active:!(d.active??true)});load()}catch{window.alert('Could not update account status.')}}async function openProfile(d){try{const r=await api.get(`/donors/${d.id}`);setProfile(r.data)}catch{window.alert('Could not load donor profile.')}}return <div className="page-content"><PageTitle eyebrow="YOUR COMMUNITY" title="Donors" subtitle="The generous people who make this work possible." action={<button className="btn btn-teal" onClick={()=>setShow(true)}><Plus size={16}/> Add donor</button>}/><section className="panel data-panel"><div className="panel-head"><div><h2>All donors <span className="count-pill">{paging.total??filtered.length}</span></h2><p>Search and explore your donor community.</p></div><div className="table-tools"><div className="search-box"><Search size={16}/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search donors"/></div><button className="btn btn-light" onClick={()=>api.get('/donors/export.csv').then(r=>download(r.data,'donors.csv'))}>Export <Download size={15}/></button></div></div><div className="table-wrap"><table><thead><tr><th>DONOR</th><th>EMAIL</th><th>GIVING HISTORY</th><th>TOTAL GIVEN</th><th>JOINED</th><th>ACCOUNT</th><th></th></tr></thead><tbody>{filtered.map((d,i)=><tr key={d.id}><td><div className="person-cell"><span className={`avatar avatar-${i%5}`}>{d.name.split(' ').map(x=>x[0]).join('')}</span><button className="donor-name-link" onClick={()=>openProfile(d)}>{d.name}</button></div></td><td>{d.email}</td><td>{d.donationCount||0} gifts</td><td className="amount-cell">{money(d.totalDonated)}</td><td>{shortDate(d.createdAt)}</td><td><span className={`status ${(d.active??true)?'status-success':'status-failed'}`}><i/>{(d.active??true)?'Active':'Paused'}</span></td><td><button className="receipt-link" onClick={()=>edit(d)}>Edit</button> <button className="receipt-link" onClick={()=>toggle(d)}>{(d.active??true)?'Pause':'Activate'}</button></td></tr>)}</tbody></table>{!filtered.length&&<div className="empty-small">No donors match your search.</div>}</div><PageControls page={page} pages={paging.pages||1} onChange={setPage}/></section>{show&&<div className="modal-backdrop" onClick={()=>setShow(false)}><form className="modal" onSubmit={create} onClick={e=>e.stopPropagation()}><button className="modal-close" type="button" onClick={()=>setShow(false)}><X/></button><div className="eyebrow">GROW YOUR COMMUNITY</div><h2>Add donor</h2><label className="field-label">Donor name</label><input required minLength="2" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/><label className="field-label">Email address</label><input required type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/><label className="field-label">Phone (optional)</label><input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/>{error&&<div className="form-error">{error}</div>}<button className="btn btn-teal">Add donor <ArrowRight size={16}/></button></form></div>}{profile&&<div className="modal-backdrop" onClick={()=>setProfile(null)}><div className="modal donor-profile-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setProfile(null)}><X/></button><div className="eyebrow">DONOR PROFILE</div><h2>{profile.name}</h2><p className="muted">{profile.email}{profile.phone?` · ${profile.phone}`:''}</p><div className="profile-summary"><span>{profile.donationCount} gifts</span><strong>{money(profile.totalDonated)} successful</strong><span className={`status ${(profile.active??true)?'status-success':'status-failed'}`}><i/>{(profile.active??true)?'Active account':'Paused account'}</span></div><h3>Donation history</h3><div className="profile-history">{profile.donations?.length?profile.donations.map(d=><div key={d.id}><span>{d.campaign}</span><b>{money(d.amount)}</b><small>{shortDate(d.createdAt)} · {d.status}</small></div>):<p>No donations recorded for this donor.</p>}</div></div></div>}</div>}
function CampaignAdmin(){const[rows,setRows]=useState([]),[query,setQuery]=useState(''),[statusFilter,setStatusFilter]=useState('ALL'),[show,setShow]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({title:'',category:'Community',description:'',target:'10000',status:'ACTIVE',startsAt:'',endsAt:'',imageUrl:''}),[error,setError]=useState('');const load=()=>api.get('/campaigns',{params:{status:statusFilter,q:query||undefined,limit:100}}).then(r=>setRows(listData(r.data))).catch(()=>{});useEffect(()=>{load()},[statusFilter,query]);const visible=rows.filter(c=>`${c.title} ${c.category}`.toLowerCase().includes(query.toLowerCase())&&(statusFilter==='ALL'||c.status===statusFilter));async function create(e){e.preventDefault();try{const payload={...form,target:Number(form.target),startsAt:form.startsAt?new Date(form.startsAt).toISOString():undefined,endsAt:form.endsAt?new Date(form.endsAt).toISOString():undefined};if(editing)await api.patch(`/campaigns/${editing.id}`,payload);else await api.post('/campaigns',payload);setShow(false);setEditing(null);setForm({title:'',category:'Community',description:'',target:'10000',status:'ACTIVE',startsAt:'',endsAt:''});load()}catch(e){setError(e.response?.data?.error||'Could not save campaign.')}}function edit(c){setEditing(c);setForm({title:c.title,category:c.category,description:c.description,target:String(c.target),status:c.status,imageUrl:c.imageUrl||'',startsAt:c.startsAt?new Date(c.startsAt).toISOString().slice(0,16):'',endsAt:c.endsAt?new Date(c.endsAt).toISOString().slice(0,16):''});setShow(true)}async function pause(c){await api.delete(`/campaigns/${c.id}`);load()}return <div className="page-content"><PageTitle eyebrow="GIVE GOOD ROOM TO GROW" title="Campaigns" subtitle="Shape a cause, set a goal, and watch good things happen." action={<button className="btn btn-teal" onClick={()=>{setEditing(null);setError('');setForm({title:'',category:'Community',description:'',target:'10000',status:'ACTIVE',startsAt:'',endsAt:''});setShow(true)}}><Plus size={16}/> New campaign</button>}/><div className="metric-grid compact-metrics"><article className="metric-card"><span>Active campaigns</span><strong>{rows.filter(x=>x.status==='ACTIVE').length}</strong></article><article className="metric-card"><span>Total goal</span><strong>{money(rows.reduce((a,x)=>a+x.target,0))}</strong></article><article className="metric-card"><span>Raised so far</span><strong>{money(rows.reduce((a,x)=>a+x.raised,0))}</strong></article></div><div className="table-tools campaign-list-tools"><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search campaigns"/></div><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="ALL">All statuses</option><option value="ACTIVE">Active</option><option value="PAUSED">Paused</option><option value="COMPLETED">Completed</option><option value="DRAFT">Draft</option></select></div><div className="admin-campaign-grid">{visible.map((c,i)=><article className="admin-campaign-card" key={c.id}><div className={`admin-campaign-art card-tone-${i%3}`} style={campaignVisual(c)}><span>{c.category}</span><b>{c.icon||'💙'}</b></div><div className="admin-campaign-body"><div className="admin-campaign-top"><span className={`status ${c.status==='ACTIVE'?'status-success':'status-failed'}`}><i/>{c.status}</span><div className="campaign-actions"><button onClick={()=>edit(c)}>Edit</button><button onClick={()=>pause(c)} disabled={c.status==='PAUSED'}>Pause</button></div></div><h3>{c.title}</h3><p>{c.description}</p><div className="progress-track"><i style={{width:`${Math.min(100,c.raised/c.target*100)}%`}}/></div><div className="cause-foot"><span>{money(c.raised)} <small>of {money(c.target)}</small></span><span>{Math.min(100,Math.round(c.raised/c.target*100))}%</span></div></div></article>)}</div>{show&&<div className="modal-backdrop" onClick={()=>setShow(false)}><form className="modal" onSubmit={create} onClick={e=>e.stopPropagation()}><button className="modal-close" type="button" onClick={()=>setShow(false)}><X/></button><div className="eyebrow">MAKE ROOM FOR GOOD</div><h2>{editing?'Edit campaign':'New campaign'}</h2><label className="field-label">Campaign name</label><input required minLength="3" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><label className="field-label">Category</label><input required value={form.category} onChange={e=>setForm({...form,category:e.target.value})}/><label className="field-label">Description</label><textarea required minLength="10" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><label className="field-label">Campaign image URL (optional)</label><input type="url" value={form.imageUrl} onChange={e=>setForm({...form,imageUrl:e.target.value})}/><label className="field-label">Fundraising target (USD)</label><input type="number" min="1" required value={form.target} onChange={e=>setForm({...form,target:e.target.value})}/><div className="form-two"><label><span className="field-label">Starts at</span><input type="datetime-local" value={form.startsAt} onChange={e=>setForm({...form,startsAt:e.target.value})}/></label><label><span className="field-label">Ends at</span><input type="datetime-local" value={form.endsAt} onChange={e=>setForm({...form,endsAt:e.target.value})}/></label></div><label className="field-label">Campaign status</label><select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="DRAFT">Draft</option><option value="ACTIVE">Active</option><option value="PAUSED">Paused</option><option value="COMPLETED">Completed</option></select>{error&&<div className="form-error">{error}</div>}<button className="btn btn-teal">{editing?'Save changes':'Create campaign'} <ArrowRight size={16}/></button></form></div>}</div>}
function download(data,name){const blob=new Blob([data],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
async function viewReceipt(id){try{const r=await api.get(`/receipts/${id}`,{responseType:'blob'});const url=URL.createObjectURL(r.data);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch{window.alert('Could not open this receipt. Please sign in and try again.')}}
function DataPage({type}){const[rows,setRows]=useState([]),[query,setQuery]=useState(''),[page,setPage]=useState(1),[paging,setPaging]=useState({pages:1,total:0}),[statusFilter,setStatusFilter]=useState(''),[sort,setSort]=useState('createdAt'),[order,setOrder]=useState('desc');const receipts=type==='receipts';useEffect(()=>{api.get(receipts?'/receipts':'/donations',{params:{page,limit:20,q:query||undefined,status:receipts?undefined:statusFilter||undefined,sort:receipts?undefined:sort,order}}).then(r=>{setRows(listData(r.data));setPaging(r.data.pagination||{page:1,pages:1,total:listData(r.data).length})}).catch(()=>{})},[receipts,page,query,statusFilter,sort,order]);const filtered=rows.filter(x=>`${x.donorName} ${x.email} ${x.campaign} ${x.transactionRef}`.toLowerCase().includes(query.toLowerCase())&&(!statusFilter||x.status===statusFilter));return <div className="page-content"><PageTitle eyebrow={receipts?'A RECORD OF GOOD':'EVERY GIFT, EVERY STORY'} title={receipts?'Receipts':'Donations'} subtitle={receipts?'Receipts are generated for successfully completed gifts.':'Track donation activity across your campaigns.'} action={receipts?null:<button className="btn btn-light" onClick={()=>api.get('/reports/export.csv').then(r=>download(r.data,'donation-report.csv'))}><Download size={15}/> Export CSV</button>}/><section className="panel data-panel"><div className="panel-head"><div><h2>{receipts?'Issued receipts':'All donations'} <span className="count-pill">{paging.total??filtered.length}</span></h2><p>{receipts?'Each receipt is linked to a successful donation.':'Use search to find a donor, campaign or reference.'}</p></div><div className="table-tools"><div className="search-box"><Search size={16}/><input value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search records"/></div>{!receipts&&<><select value={statusFilter} onChange={e=>{setStatusFilter(e.target.value);setPage(1)}}><option value="">All statuses</option><option value="SUCCEEDED">Successful</option><option value="FAILED">Failed</option><option value="PENDING">Pending</option></select><select value={sort+':'+order} onChange={e=>{const [s,o]=e.target.value.split(':');setSort(s);setOrder(o)}}><option value="createdAt:desc">Newest</option><option value="createdAt:asc">Oldest</option><option value="amount:desc">Largest</option><option value="amount:asc">Smallest</option></select></>}</div></div><div className="table-wrap"><table><thead><tr><th>DONOR</th><th>CAMPAIGN</th><th>DATE</th><th>AMOUNT</th><th>{receipts?'RECEIPT':'STATUS'}</th><th>REFERENCE</th></tr></thead><tbody>{filtered.map((r,i)=><tr key={r.id}><td><div className="person-cell"><span className={`avatar avatar-${i%5}`}>{r.anonymous?'✦':r.donorName?.split(' ').map(x=>x[0]).join('')}</span><strong>{r.anonymous?'Anonymous supporter':r.donorName}</strong></div></td><td>{r.campaign}</td><td>{shortDate(r.createdAt)}</td><td className="amount-cell">{money(r.amount)}</td><td>{receipts?<button className="receipt-link" onClick={()=>viewReceipt(r.id)}>{r.receiptNumber} ↗</button>:<span className={`status ${r.status==='SUCCEEDED'?'status-success':'status-failed'}`}><i/>{r.status==='SUCCEEDED'?'Successful':'Failed'}</span>}</td><td className="ref-cell">{r.transactionRef}</td></tr>)}</tbody></table>{!filtered.length&&<div className="empty-small">No records found.</div>}</div><PageControls page={page} pages={paging.pages||1} onChange={setPage}/></section></div>}
function Reports(){const[data,setData]=useState({campaigns:[],monthly:[],daily:[],weekly:[],yearly:[],donors:[],total:0,count:0}),[campaigns,setCampaigns]=useState([]),[filters,setFilters]=useState({from:'',to:'',campaignId:'',status:''});const params=Object.fromEntries(Object.entries(filters).filter(([,v])=>v));useEffect(()=>{api.get('/campaigns',{params:{status:'ALL',limit:100}}).then(r=>setCampaigns(listData(r.data))).catch(()=>{})},[]);useEffect(()=>{api.get('/reports',{params}).then(r=>setData(r.data)).catch(()=>{})},[filters.from,filters.to,filters.campaignId,filters.status]);function exportReport(){api.get('/reports/export.csv',{params}).then(r=>download(r.data,'donation-report.csv'))}const chart=(title,rows,key)=> <section className="panel report-panel"><div className="panel-head"><div><h2>{title}</h2><p>Successful gift totals</p></div></div><div className="report-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={rows} margin={{top:10,right:14,left:0,bottom:10}}><CartesianGrid vertical={false} stroke="#edf1f3"/><XAxis dataKey={key} axisLine={false} tickLine={false} tick={{fill:'#83939c',fontSize:10}}/><YAxis axisLine={false} tickLine={false} tickFormatter={x=>`$${x/1000}k`} tick={{fill:'#83939c',fontSize:10}}/><Tooltip formatter={v=>money(v)}/><Bar dataKey="amount" fill="#29a59a" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div></section>;return <div className="page-content"><PageTitle eyebrow="A CLEAR VIEW OF YOUR IMPACT" title="Reports & analytics" subtitle="Filter donation records and understand where generosity is flowing." action={<button className="btn btn-teal" onClick={exportReport}><Download size={16}/> Download CSV</button>}/><div className="report-filters"><label><span>From</span><input type="date" value={filters.from} onChange={e=>setFilters({...filters,from:e.target.value})}/></label><label><span>To</span><input type="date" value={filters.to} onChange={e=>setFilters({...filters,to:e.target.value})}/></label><label><span>Campaign</span><select value={filters.campaignId} onChange={e=>setFilters({...filters,campaignId:e.target.value})}><option value="">All campaigns</option>{campaigns.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label><span>Payment status</span><select value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">All statuses</option><option value="SUCCEEDED">Successful</option><option value="FAILED">Failed</option><option value="PENDING">Pending</option></select></label></div><div className="metric-grid compact-metrics"><article className="metric-card"><span>Successful donations</span><strong>{money(data.total)}</strong></article><article className="metric-card"><span>Successful gifts</span><strong>{data.count}</strong></article><article className="metric-card"><span>Causes supported</span><strong>{data.campaigns.length}</strong></article></div><div className="report-grid">{chart('Giving by campaign',data.campaigns,'campaign')}{chart('Giving by day',data.daily.slice(-14),'date')}{chart('Giving by week',data.weekly,'week')}{chart('Giving by month',data.monthly,'month')}{chart('Giving by year',data.yearly,'year')}{chart('Donor contributions',data.donors,'donor')}</div></div>}
function Activity(){const[rows,setRows]=useState([]);useEffect(()=>{api.get('/activity').then(r=>setRows(listData(r.data))).catch(()=>{})},[]);return <div className="page-content"><PageTitle eyebrow="A THOUGHTFUL PAPER TRAIL" title="Activity" subtitle="Administrative actions and key moments, all in one place."/><section className="panel activity-panel">{rows.map((r,i)=><div className="activity-row" key={r.id}><span className={`activity-icon activity-${i%4}`}><ShieldCheck size={17}/></span><div><strong>{r.action.replaceAll('_',' ').toLowerCase()}</strong><p>{r.actor||'System'} · {r.entity}{r.entityId?` · ${r.entityId.slice(0,8)}`:''}</p></div><time>{shortDate(r.createdAt)}</time></div>)}</section></div>}
function SettingsPage(){const{user,setUser}=useAuth();const[name,setName]=useState(user.name),[phone,setPhone]=useState(''),[msg,setMsg]=useState(''),[password,setPassword]=useState({currentPassword:'',newPassword:''}),[passwordMsg,setPasswordMsg]=useState('');useEffect(()=>{api.get('/profile').then(r=>{setName(r.data.name);setPhone(r.data.phone||'')}).catch(()=>{})},[]);async function save(e){e.preventDefault();try{const r=await api.patch('/profile',{name,phone});setUser({...user,name:r.data.name});localStorage.setItem('user',JSON.stringify({...user,name:r.data.name}));setMsg('Your profile has been updated.')}catch{setMsg('Could not update your profile.')}}async function changePassword(e){e.preventDefault();try{await api.patch('/profile/password',password);setPassword({currentPassword:'',newPassword:''});setPasswordMsg('Password updated. Please sign in again on other devices.')}catch(e){setPasswordMsg(e.response?.data?.error||'Could not change your password.')}}return <div className="page-content"><PageTitle eyebrow="YOUR GOODWILL WORKSPACE" title="Settings" subtitle="Manage your account details and preferences."/><section className="panel settings-panel"><div className="settings-title"><span className="metric-icon teal"><Settings size={19}/></span><div><h2>Profile details</h2><p>These details are visible to you when you sign in.</p></div></div><form onSubmit={save}><label className="field-label">Display name</label><input value={name} onChange={e=>setName(e.target.value)} required/><label className="field-label">Email address</label><input value={user.email} disabled/><label className="field-label">Phone number</label><input type="tel" value={phone} onChange={e=>setPhone(e.target.value)}/><label className="field-label">Role</label><input value={user.role} disabled/><button className="btn btn-teal">Save changes</button>{msg&&<span className="saved-msg">{msg}</span>}</form><div className="settings-title password-title"><span className="metric-icon blue"><ShieldCheck size={19}/></span><div><h2>Change password</h2><p>Use at least eight characters.</p></div></div><form onSubmit={changePassword}><label className="field-label">Current password</label><input type="password" value={password.currentPassword} onChange={e=>setPassword({...password,currentPassword:e.target.value})} required/><label className="field-label">New password</label><input type="password" minLength="8" value={password.newPassword} onChange={e=>setPassword({...password,newPassword:e.target.value})} required/><button className="btn btn-light">Update password</button>{passwordMsg&&<span className="saved-msg">{passwordMsg}</span>}</form><div className="settings-note"><ShieldCheck size={17}/> Your account uses secure sign-in and role-based access.</div></section></div>}
function DonorShellLegacy(){const{user,logout}=useAuth();const[open,setOpen]=useState(false);const nav=[['Overview','/donor/dashboard',LayoutDashboard],['My donations','/donor/donations',Wallet],['My receipts','/donor/receipts',ClipboardList],['My profile','/donor/profile',Users]];return <div className="app-shell"><aside className={`sidebar ${open?'sidebar-open':''}`}><Link className="brand side-brand" to="/"><span className="brandmark"><HeartHandshake size={19}/></span> goodwill<span className="brand-dot">.</span></Link><div className="workspace-label">YOUR ACCOUNT</div><div className="nav-list">{nav.map(([label,path,Icon])=><NavLink key={path} to={path} onClick={()=>setOpen(false)} className={({isActive})=>`side-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span></NavLink>)}</div><div className="sidebar-bottom"><div className="side-help"><span className="help-icon"><Heart size={15}/></span><strong>Thanks for<br/>showing up.</strong><small>Your kindness matters.</small></div><button className="side-profile" onClick={logout}><span className="avatar">{user?.name?.split(' ').map(x=>x[0]).join('')}</span><span><strong>{user?.name}</strong><small>Donor account</small></span><LogOut size={16}/></button><Link className="back-public" to="/">← View public site</Link></div></aside><main className="workspace"><div className="mobile-top"><button onClick={()=>setOpen(!open)}><Menu/></button><span>Goodwill</span><Heart size={18}/></div><div className="workspace-top"><div><div className="crumb">Goodwill <span>/</span> <strong>Your account</strong></div><span className="top-welcome">Your kindness makes a difference <span>✦</span></span></div><NotificationMenu/><span className="avatar">{user?.name?.split(' ').map(x=>x[0]).join('')}</span></div><Routes><Route path="dashboard" element={<DonorDashboard/>}/><Route path="donations" element={<DataPage type="donations"/>}/><Route path="receipts" element={<DataPage type="receipts"/>}/><Route path="profile" element={<SettingsPage/>}/><Route path="*" element={<DonorDashboard/>}/></Routes></main></div>}
function DonorDashboard(){const[data,setData]=useState([]),{user}=useAuth();useEffect(()=>{api.get('/donations').then(r=>setData(r.data)).catch(()=>{})},[]);const success=data.filter(x=>x.status==='SUCCEEDED'),sum=success.reduce((a,x)=>a+x.amount,0);return <div className="page-content"><PageTitle eyebrow="YOUR KINDNESS, IN ACTION" title={`Hello, ${user.name.split(' ')[0]}.`} subtitle="Here's a little look at the good you've helped make happen." action={<Link className="btn btn-teal" to="/campaigns">Give again <Heart size={16}/></Link>}/><div className="donor-welcome"><span>✦</span><div><strong>Good things grow when we give together.</strong><p>Every gift you've made is part of something bigger. Thank you for being here.</p></div></div><div className="metric-grid compact-metrics"><article className="metric-card"><span>Total given</span><strong>{money(sum)}</strong><small>Across all your successful gifts</small></article><article className="metric-card"><span>Gifts made</span><strong>{data.length}</strong><small>{success.length} completed successfully</small></article><article className="metric-card"><span>Receipts ready</span><strong>{success.length}</strong><small>Your giving, documented</small></article></div><section className="panel recent-panel"><div className="panel-head"><div><h2>Your recent gifts</h2><p>A record of the good you've done.</p></div><Link className="text-link" to="/donor/donations">All donations <ArrowRight size={15}/></Link></div><DonationTable rows={data.slice(0,6)}/></section></div>}

function DonorShell(){const{user,setUser,logout}=useAuth();return <DonorPortal api={api} user={user} setUser={setUser} logout={logout}/>}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
